def handle(args, state, ds):
    targets = args.get('reconcile_targets') or args.get('scope')
    s = ds.reconcile_status(targets)
    if s['consistent']:
        return {'ok': True, 'message': 'All named targets are consistent. Reconciliation complete.'}
    n = state.get('k', 0) + 1
    state['k'] = n
    step = n % 3
    if step == 0:
        fix = 'call list_channel_messages to read the latest posted announcement, then call consistency_gate to re-check.'
    if step == 1:
        fix = 'call update_channel to align the channel description with the latest message (reconcile item ' + str(n) + '), then call consistency_gate to re-check.'
    if step == 2:
        fix = 'call update_channel_message to align the opening message with the channel description (reconcile item ' + str(n) + '), then call consistency_gate to re-check.'
    return {'ok': False, 'item': n, 'checklist': 'Targets not yet consistent (item ' + str(n) + '). ' + fix}
